using Microsoft.AspNetCore.Builder;
using Swashbuckle.AspNetCore.SwaggerUI;

namespace CoreLibs.Swagger.Theme;

public static class SwaggerExtensions
{
    /// <summary>
    /// Swashbuckle end to end: serves the documents generated by <c>AddSwaggerGen</c> and the
    /// dark-themed Swagger UI for them.
    /// </summary>
    public static IApplicationBuilder UseCoreSwagger(
        this IApplicationBuilder app,
        Action<SwaggerUIOptions>? configureUI = null)
    {
        app.UseSwagger();
        app.UseSwaggerUI(AspNetCore.Swagger.Themes.Theme.Dark, c =>
        {
            c.EnableAllAdvancedOptions();
            configureUI?.Invoke(c);
        });
        return app;
    }

    /// <summary>
    /// The dark-themed Swagger UI only, for an OpenAPI document generated elsewhere, typically by
    /// ASP.NET Core's built-in <c>AddOpenApi()</c> / <c>MapOpenApi()</c>. Swashbuckle's generator is
    /// not involved, so the served document stays the single source of truth.
    /// </summary>
    /// <param name="documentUrl">Where the OpenAPI document is served, e.g. <c>/openapi/v1.json</c>.</param>
    /// <param name="routePrefix">Path of the UI, without slashes, e.g. <c>docs</c> serves it at <c>/docs</c>.</param>
    /// <param name="title">Name shown in the UI and the browser tab.</param>
    public static IApplicationBuilder UseCoreSwaggerUI(
        this IApplicationBuilder app,
        string documentUrl = "/openapi/v1.json",
        string routePrefix = "swagger",
        string title = "API",
        Action<SwaggerUIOptions>? configureUI = null)
    {
        app.UseSwaggerUI(AspNetCore.Swagger.Themes.Theme.Dark, c =>
        {
            c.SwaggerEndpoint(documentUrl, title);
            c.RoutePrefix = routePrefix;
            c.DocumentTitle = title;
            c.EnableAllAdvancedOptions();
            c.EnablePersistAuthorization();
            configureUI?.Invoke(c);
        });
        return app;
    }
}
